 void loadAirlineLogo(ImageView v,String code,String name){if(code==null||code.isEmpty()){v.setImageDrawable(g(O,18));return;}new Thread(()->{try{URL u=new URL("https://images.kiwi.com/airlines/64/"+code+".png");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);Bitmap b=BitmapFactory.decodeStream(c.getInputStream());runOnUiThread(()->{if(b!=null)v.setImageBitmap(b);else v.setImageDrawable(g(O,18));});}catch(Exception e){runOnUiThread(()->v.setImageDrawable(g(O,18)));}}).start();}
 Offer testOffer(String origin,String destination){Offer a=new Offer("Vicationfly Test Airlines","VF",origin,destination,"2027-07-01T09:00:00","2027-07-01T13:00:00",240,1,"0","USD");a.test=true;JSONArray z=new JSONArray();try{z.put(new JSONObject().put("marketing_carrier_code","VF").put("marketing_carrier_name","Vicationfly Test Airlines").put("flight_number","VF101").put("departure_airport",origin).put("arrival_airport","TST").put("departure_time_local","2027-07-01T09:00:00").put("arrival_time_local","2027-07-01T10:45:00"));z.put(new JSONObject().put("marketing_carrier_code","VF").put("marketing_carrier_name","Vicationfly Test Airlines").put("flight_number","VF202").put("departure_airport","TST").put("arrival_airport",destination).put("departure_time_local","2027-07-01T11:30:00").put("arrival_time_local","2027-07-01T13:00:00"));}catch(Exception e){}a.segments=z;return a;} Offer testConnectionOffer(String origin,String destination){Offer a=testOffer(origin,destination);a.airline="Vicationfly Test Connection";a.carrier="VF";a.departAt="2027-07-02T08:00:00";a.arriveAt="2027-07-02T14:00:00";a.duration=360;a.stops=1;a.test=true;return a;}
 void seatSelection(Offer flight,String origin,String destination){base();top("Choose Seats",flight.airline+" · "+origin+" → "+destination,true);int paxTotal=adults+children;int legCount=flight.segments==null?Math.max(1,flight.stops+1):Math.max(1,flight.segments.length());body.addView(t("Seats required: "+paxTotal+" passenger"+(paxTotal>1?"s":"")+" × "+legCount+" flight"+(legCount>1?"s":"")+" = "+(paxTotal*legCount)+" selections.",14,M,false));body.addView(space(8));if(!flight.test&&flight.provider.equalsIgnoreCase("Duffel")&&flight.offerId.length()>0&&FLIGHT_GATEWAY_URL.length()>0){body.addView(t("Loading the airline's live seat map…",14,INK,true));new Thread(()->loadLiveSeatMap(flight,origin,destination)).start();return;}if(!flight.test){LinearLayout unavailable=new LinearLayout(this);unavailable.setOrientation(LinearLayout.VERTICAL);unavailable.setPadding(d(18),d(20),d(18),d(20));unavailable.setBackground(s(Color.WHITE,LINE,22));unavailable.addView(t("Live seat map unavailable",19,INK,true));unavailable.addView(t("This provider did not return a verifiable seat map for this offer. Vicationfly will not invent occupied seats or aircraft layouts.",13,M,false));body.addView(unavailable);return;}drawTestSeatMaps(flight,origin,destination,paxTotal);}
void loadLiveSeatMap(Offer flight,String origin,String destination){try{URL u=new URL(FLIGHT_GATEWAY_URL+"/v1/flights/seat-map");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);JSONObject q=new JSONObject().put("provider",flight.provider).put("offerId",flight.offerId);c.getOutputStream().write(q.toString().getBytes("UTF-8"));int code=c.getResponseCode();BufferedReader r=new BufferedReader(new InputStreamReader(code>=200&&code<300?c.getInputStream():c.getErrorStream()));StringBuilder z=new StringBuilder();String line;while((line=r.readLine())!=null)z.append(line);r.close();if(code<200||code>=300)throw new Exception("Seat map HTTP "+code);JSONObject root=new JSONObject(z.toString());JSONArray maps=root.optJSONArray("seatMaps");if(maps==null||maps.length()==0)throw new Exception("The airline did not provide a seat map for this offer.");runOnUiThread(()->drawLiveSeatMaps(flight,origin,destination,maps));}catch(Exception e){runOnUiThread(()->{body.removeAllViews();top("Choose Seats","Live airline seat map",true);body.addView(t("No verified seat map is available for this flight.",18,INK,true));body.addView(t(e.getMessage(),13,M,false));});}}
void drawLiveSeatMaps(Offer flight,String origin,String destination,JSONArray maps){body.removeAllViews();top("Choose Seats","Live airline seat maps",true);int paxTotal=adults+children;ArrayList<String> selected=new ArrayList<>();for(int m=0;m<maps.length();m++){JSONObject map=maps.optJSONObject(m);if(map==null)continue;body.addView(t("Flight "+(m+1)+"  ·  "+map.optString("segment",""),17,INK,true));JSONArray seats=map.optJSONArray("seats");if(seats==null)continue;LinearLayout grid=new LinearLayout(this);grid.setOrientation(LinearLayout.VERTICAL);grid.setPadding(d(10),d(10),d(10),d(10));grid.setBackground(s(Color.WHITE,LINE,22));for(int i=0;i<seats.length();i++){JSONObject seat=seats.optJSONObject(i);if(seat==null)continue;Button b=new Button(this);String code=seat.optString("designator","?");boolean available=seat.optBoolean("available",false);b.setText(code);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackground(g(available?Color.rgb(46,180,95):Color.GRAY,10));b.setEnabled(available);b.setOnClickListener(v->{if(selected.contains(code)){selected.remove(code);b.setBackground(g(Color.rgb(46,180,95),10));}else if(selected.size()<paxTotal*maps.length()){selected.add(code);b.setBackground(g(O,10));}else toast("You have selected the required number of seats.");});grid.addView(b,lp(-1,d(44)));}body.addView(grid);body.addView(space(10));}Button buy=B("Buy Now");buy.setOnClickListener(v->{if(selected.size()!=paxTotal*maps.length()){toast("Select "+(paxTotal*maps.length())+" seats across the flight segments.");return;}payment(flight,origin,destination,selected.size());});body.addView(buy,lp(-1,d(62)));}
