JSONObject httpJson(String url,JSONObject q)throws Exception{URL u=new URL(url);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(12000);c.setReadTimeout(30000);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Accept","application/json");c.setDoOutput(true);c.getOutputStream().write(q.toString().getBytes("UTF-8"));int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();BufferedReader r=new BufferedReader(new InputStreamReader(in));StringBuilder z=new StringBuilder();String line;while((line=r.readLine())!=null)z.append(line);r.close();if(code<200||code>=300)throw new Exception("HTTP "+code);return new JSONObject(z.toString());}
